```jsx
import { useState } from 'react';

export default function Counter() {
  const [count, setCount] = useState(0);

  function addTwo() {
    setCount(current => current + 1);
    setCount(current => current + 1);
    console.log(count); // current render's snapshot: 0
  }

  return <button onClick={addTwo}>Count: {count}</button>;
}
```
One click produces 2 in the next render because the second updater receives the first updater's result.

