import { useState } from 'react';

function ProductSearch({ products }) {
  const [query, setQuery] = useState('');
  const [inStockOnly, setInStockOnly] = useState(false);

  const visibleProducts = products.filter(product =>
    product.name.toLowerCase().includes(query.toLowerCase()) &&
    (!inStockOnly || product.inStock)
  );

  return <ProductTable products={visibleProducts} />;
}
```
The visible products are always derived from the current render's three inputs, so there is no Effect or duplicate collection to synchronize.

```jsx
const [todos, setTodos] = useState(initialTodos);

function addTodo(todo) {
  setTodos(current => [...current, todo]);
}

function toggleTodo(id) {
  setTodos(current => current.map(todo =>
    todo.id === id ? { ...todo, done: !todo.done } : todo
  ));
}

function removeTodo(id) {
  setTodos(current => current.filter(todo => todo.id !== id));
}
```
Each operation returns a replacement array; only a toggled item receives a replacement object.

```jsx
function requestReducer(state, action) {
  switch (action.type) {
    case 'submit':
      return { status: 'submitting', data: null, error: null };
    case 'resolve':
      return { status: 'success', data: action.data, error: null };
    case 'reject':
      return { status: 'error', data: null, error: action.message };
    default:
      throw new Error(`Unknown action: ${action.type}`);
  }
}

const [request, dispatch] = useReducer(requestReducer, { status: 'idle', data: null, error: null });
```
One action produces one complete request state, so loading, success, and error cannot accidentally overlap.
